func TestPayment(t *testing.T) {
	m := setupMeter(t)
	if _, err := m.ReportUsage("a1", "e1", time.Date(2026, 1, 15, 0, 0, 0, 0, UTC), 150); err != nil {
		t.Fatal(err)
	}
	if _, err := m.GenerateBill("a1", 2026, time.January); err != nil {
