		t.Fatal(err)
	}
	bal, err := m.BillBalance("a1", 2026, time.January)
	if err != nil {
		t.Fatal(err)
	}
	if bal != 575 {
		t.Fatalf("余额应为 575，得到 %d", bal)
	}
	if pay.Amount != 1000 {
		t.Fatalf("付款金额错误：%+v", pay)
	}

	// 相同账单与金额的重报返回原结果。
	pay2, err := m.RegisterPayment("a1", "pay1", 2026, time.January, 1000)
	if err != nil {
		t.Fatal(err)
	}
	if pay2 != pay {
