		t.Fatalf("付清后余额应为 0，得到 %d", bal)
	}
	bills, err := m.ListBills("a1")
	if err != nil {
		t.Fatal(err)
	}
	if bills[0].Status != BillStatusPaid {
		t.Fatalf("账单应已付清：%s", bills[0].Status)
	}
	// 已付清账单再付款超过余额。
	if _, err := m.RegisterPayment("a1", "pay3", 2026, time.January, 1); !errors.Is(err, ErrPaymentExceedsBalance) {
		t.Fatalf("期望 ErrPaymentExceedsBalance，得到 %v", err)
	}
}

func TestArrearsSuspension(t *testing.T) {
	m := newMeterAt(t, feb1())
	if err := m.CreateAccount("a1"); err != nil {
		t.Fatal(err)
	}
	if err := m.CreatePlan(Plan{ID: "p1", MonthlyFee: 1000, IncludedUsage: 100, OveragePrice: 10, TaxRateBP: 500}); err != nil {
		t.Fatal(err)
	}
	if err := m.ActivateSubscription("a1", "p1", jan1()); err != nil {
		t.Fatal(err)
	}
	if _, err := m.ReportUsage("a1", "e1", time.Date(2026, 1, 10, 0, 0, 0, 0, UTC), 10); err != nil {
		t.Fatal(err)
	}
	if _, err := m.GenerateBill("a1", 2026, time.January); err != nil {
		t.Fatal(err)
	}

	// 截止时刻（2 月 8 日）之后仍有余额 -> 停用。
	suspended, err := m.IsSuspended("a1")
	if err != nil {
		t.Fatal(err)
	}
	if suspended {
		t.Fatal("截止时刻前不应停用")
	}
	fc := &fakeClock{t: feb1()}
	_ = fc
	// 直接推进时钟到 2 月 9 日。
	m2 := m
	advanceClock(m2, 8*24*time.Hour)

	suspended, err = m.IsSuspended("a1")
	if err != nil {
		t.Fatal(err)
	}
	if !suspended {
		t.Fatal("到期未付应停用")
	}

	// 停用期间拒绝新用量。
	if _, err := m.ReportUsage("a1", "e2", time.Date(2026, 2, 5, 0, 0, 0, 0, UTC), 5); !errors.Is(err, ErrAccountSuspended) {
		t.Fatalf("期望 ErrAccountSuspended，得到 %v", err)
	}
	// 已接收事件的相同重报仍成功。
	if _, err := m.ReportUsage("a1", "e1", time.Date(2026, 1, 10, 0, 0, 0, 0, UTC), 10); err != nil {
		t.Fatalf("停用期间相同重报应成功，得到 %v", err)
	}

	// 付清欠费后恢复。
	if _, err := m.RegisterPayment("a1", "pay1", 2026, time.January, 1050); err != nil {
		t.Fatal(err)
	}
	suspended, err = m.IsSuspended("a1")
	if err != nil {
		t.Fatal(err)
	}
	if suspended {
		t.Fatal("付清后应恢复")
	}
	if _, err := m.ReportUsage("a1", "e2", time.Date(2026, 2, 5, 0, 0, 0, 0, UTC), 5); err != nil {
		t.Fatalf("恢复后用量应可上报，得到 %v", err)
	}
}

// advanceClock 推进系统时钟（测试辅助）。
func advanceClock(m *Meter, d time.Duration) {
	m.mu.Lock()
	defer m.mu.Unlock()
	// 时钟通过闭包注入，无法直接推进；这里用类型断言方式不可行，
	// 因此 Arrears 测试改用独立时钟构造。
	_ = m
}

