func TestConcurrency(t *testing.T) {
	m := newMeterAt(t, feb1())
	if err := m.CreateAccount("a1"); err != nil {
		t.Fatal(err)
	}
	if err := m.CreatePlan(Plan{ID: "p1", MonthlyFee: 1000, IncludedUsage: 100, OveragePrice: 10, TaxRateBP: 500}); err != nil {
		t.Fatal(err)
	}
	if err := m.ActivateSubscription("a1", "p1", jan1()); err != nil {
		t.Fatal(err)
	}

	// 并发重复提交同一事件：只累计一次。
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			_, _ = m.ReportUsage("a1", "e1", time.Date(2026, 1, 10, 0, 0, 0, 0, UTC), 10)
		}()
	}
	wg.Wait()
	got, err := m.MonthlyUsage("a1", 2026, time.January)
	if err != nil {
		t.Fatal(err)
	}
	if got != 10 {
		t.Fatalf("并发重复提交应只累计一次，得到 %d", got)
	}

	// 并发出账：只生成一张账单。
	bills := make([]*Bill, 100)
	errs := make([]error, 100)
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			bills[i], errs[i] = m.GenerateBill("a1", 2026, time.January)
		}(i)
	}
	wg.Wait()
	for i := 0; i < 100; i++ {
		if errs[i] != nil {
			t.Fatalf("出账失败：%v", errs[i])
		}
		if bills[i] != bills[0] {
			t.Fatal("并发出账应返回同一张账单")
		}
	}
	list, err := m.ListBills("a1")
	if err != nil {
		t.Fatal(err)
	}
	if len(list) != 1 {
		t.Fatalf("应只有一张账单，得到 %d", len(list))
	}

	// 并发重复付款：只扣减一次余额。
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			_, _ = m.RegisterPayment("a1", "pay1", 2026, time.January, 100)
		}()
	}
	wg.Wait()
	bal, err := m.BillBalance("a1", 2026, time.January)
	if err != nil {
		t.Fatal(err)
	}
	// 账单总额 1575，扣减一次 100 -> 余额 1475。
	if bal != 1475 {
		t.Fatalf("并发重复付款应只扣减一次，余额应为 1475，得到 %d", bal)
	}
}

