	// 直接推进时钟到 2 月 9 日。
	m2 := m
	advanceClock(m2, 8*24*time.Hour)

	suspended, err = m.IsSuspended("a1")
	if err != nil {
		t.Fatal(err)
	}
	if !suspended {
		t.Fatal("到期未付应停用")
	}

	// 停用期间拒绝新用量。
	if _, err := m.ReportUsage("a1", "e2", time.Date(2026, 2, 5, 0, 0, 0, 0, UTC), 5); !errors.Is(err, ErrAccountSuspended) {
		t.Fatalf("期望 ErrAccountSuspended，得到 %v", err)
	}
	// 已接收事件的相同重报仍成功。
	if _, err := m.ReportUsage("a1", "e1", time.Date(2026, 1, 10, 0, 0, 0, 0, UTC), 10); err != nil {
		t.Fatalf("停用期间相同重报应成功，得到 %v", err)
	}

	// 付清欠费后恢复。
	if _, err := m.RegisterPayment("a1", "pay1", 2026, time.January, 1050); err != nil {
		t.Fatal(err)
	}
	suspended, err = m.IsSuspended("a1")
	if err != nil {
		t.Fatal(err)
	}
	if suspended {
		t.Fatal("付清后应恢复")
	}
	if _, err := m.ReportUsage("a1", "e2", time.Date(2026, 2, 5, 0, 0, 0, 0, UTC), 5); err != nil {
		t.Fatalf("恢复后用量应可上报，得到 %v", err)
	}
}

// advanceClock 推进系统时钟（测试辅助）。
func advanceClock(m *Meter, d time.Duration) {
	m.mu.Lock()
	defer m.mu.Unlock()
	// 时钟通过闭包注入，无法直接推进；这里用类型断言方式不可行，
	// 因此 Arrears 测试改用独立时钟构造。
	_ = m
}

